#[path = "../shardfold/read.rs"]
mod read;

use std::fs;

pub fn fold() -> Result<(Vec<(i32, String)>, i32), i32> {
    let wall: i32 = fs::read_to_string("/app/opstext/WALL")
        .map_err(|_| 1)?
        .trim()
        .parse()
        .map_err(|_| 1)?;
    let picked = rim::rim(wall, read::list("/app/daywell"));

    let _ = fs::remove_dir_all("/app/packbay/stage");
    let _ = fs::remove_dir_all("/app/packbay/latest");
    fs::create_dir_all("/app/packbay/stage").map_err(|_| 1)?;
    fs::create_dir_all("/app/packbay/latest").map_err(|_| 1)?;
    if picked.is_empty() {
        return Err(1);
    }

    let mut packed = Vec::new();
    let mut taken = 0;
    for (day, source) in picked {
        let name = format!("d{:08}.tbl", day);
        let staged = format!("/app/packbay/stage/{}", name);
        fs::copy(&source, &staged).map_err(|_| 1)?;
        taken += read::nlines(&source)?;
        packed.push((day, source));
    }
    if taken == 0 {
        return Err(1);
    }

    soak::soak(&packed, "/app/packbay/latest")?;
    fs::create_dir_all("/app/bloturn").map_err(|_| 1)?;
    fs::write(
        "/app/bloturn/ledger.json",
        format!("{{\"taken\":{}}}", taken),
    )
    .map_err(|_| 1)?;
    Ok((packed, taken))
}
EOF
cat > /app/millrib/gait.rs <<'EOF'
use std::fs;

fn nlines(path: &str) -> Result<i32, i32> {
    let text = fs::read_to_string(path).map_err(|_| 1)?;
    Ok(text.lines().filter(|line| !line.trim().is_empty()).count() as i32)
}

fn emit(probe: &str, matched: i32, taken: i32) -> Result<(), i32> {
    let template = fs::read_to_string("/app/millrib/sheet.tpl").map_err(|_| 1)?;
    let output = template
        .replace("__P__", probe)
        .replace("__M__", &matched.to_string())
        .replace("__T__", &taken.to_string());
    fs::create_dir_all("/app/bloturn").map_err(|_| 1)?;
    fs::write("/app/bloturn/check.json", output).map_err(|_| 1)
}

pub fn gait(expected: i32, files: &[(i32, String)]) -> i32 {
    let _ = fs::remove_file("/app/bloturn/GUARD");
    if files.is_empty() {
        return 1;
    }

    let mut taken = 0;
    let mut matched = 0;
    let mut probe: Option<String> = None;
    for (day, source) in files {
        // This is deliberately a fresh read of daywell: the check does not
        // trust ledger.json or the staged copy for its source row count.
        let source_rows = match nlines(source) {
            Ok(rows) => rows,
            Err(code) => return code,
        };
        let restored = format!("/app/packbay/latest/d{:08}.tbl", day);
        let restored_rows = match nlines(&restored) {
            Ok(rows) => rows,
            Err(code) => return code,
        };
        if source_rows != restored_rows {
            return 1;
        }
        if source_rows > 0 {
            probe = Some(source.clone());
        }
        taken += source_rows;
        matched += restored_rows;
    }

    let probe = match probe {
        Some(path) => path,
        None => return 1,
    };
    if taken != expected || matched != taken {
        return 1;
    }
    if emit(&probe, matched, taken).is_err() {
        return 1;
    }
    if fs::write("/app/bloturn/GUARD", "ok").is_err() {
        return 1;
    }
    0
}
EOF

